mapper.select:
SELECT a.word_id, a.is_black, a.word_content, a.updator_id, a.updated_time, b.real_name AS updator_name FROM bt_sensitive_word a LEFT JOIN bt_user b ON b.user_id = a.updator_id WHERE a.status_cd = '00A'
AND a.is_black = #{query.isBlack}
AND a.word_content LIKE #{query.keyword}
ORDER BY a.updated_time DESC
